import { CallToAction } from './call-to-action';
import { Features } from './features';
import { Hero } from './hero';
import { LogoCloud } from './logo-cloud';
import { SiteFooter } from './site-footer';
import { SiteHeader } from './site-header';

export default function Marketing01() {
  return (
    <div className='flex min-h-screen flex-col'>
      <SiteHeader />
      <main className='flex-1'>
        <Hero />
        <LogoCloud />
        <Features />
        <CallToAction />
      </main>
      <SiteFooter />
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { Button } from '@/registry/ndeko/ui/button';
import { Collapsible } from '@/registry/ndeko/ui/collapsible';

import { LoomboardMark } from './brand-mark';
import { DesktopNav } from './desktop-nav';
import { MobileMenuPanel, MobileMenuTrigger } from './mobile-menu';
import { scrollToSection, sectionHashOf } from './section-link';

const MENU_COLLAPSE_MS = 200;

export function SiteHeader() {
  const [isOpen, setIsOpen] = useState(false);
  const [pendingHash, setPendingHash] = useState<string | null>(null);

  useEffect(() => {
    if (pendingHash === null) {
      return;
    }
    const timeout = window.setTimeout(() => {
      scrollToSection(pendingHash);
      setPendingHash(null);
    }, MENU_COLLAPSE_MS);
    return () => window.clearTimeout(timeout);
  }, [pendingHash]);

  function navigateFromMenu(event: React.MouseEvent<HTMLAnchorElement>) {
    const href = event.currentTarget.getAttribute('href');
    const sectionHash = sectionHashOf(href);
    setIsOpen(false);
    if (sectionHash === null) {
      return;
    }
    event.preventDefault();
    setPendingHash(sectionHash);
  }

  return (
    <header className='px-4 sm:px-6 lg:px-8'>
      <Collapsible
        open={isOpen}
        onOpenChange={setIsOpen}
        className='mx-auto max-w-6xl'
      >
        <div className='flex h-16 items-center gap-6'>
          <a
            href='#'
            aria-current='page'
            className='focus-visible:ring-ring/25 flex items-center gap-2 rounded-md text-sm font-semibold outline-none focus-visible:ring-[3px]'
          >
            <LoomboardMark />
            Loomboard
          </a>
          <DesktopNav />
          <div className='ms-auto hidden items-center gap-1 md:flex'>
            <Button
              variant='ghost'
              nativeButton={false}
              render={<a href='#' />}
            >
              Sign in
            </Button>
            <Button
              variant='outline'
              nativeButton={false}
              render={<a href='#' />}
            >
              Start free
            </Button>
          </div>
          <div className='ms-auto md:hidden'>
            <MobileMenuTrigger isOpen={isOpen} />
          </div>
        </div>
        <MobileMenuPanel onNavigate={navigateFromMenu} />
      </Collapsible>
    </header>
  );
}

import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  navigationMenuTriggerStyle,
} from '@/registry/ndeko/ui/navigation-menu';

import {
  FEATURED_GUIDE,
  type MenuLink,
  PRODUCT_LINKS,
  RESOURCE_LINKS,
  SOLUTION_GROUPS,
} from './data';

function IconLink({ link }: { link: MenuLink }) {
  return (
    <NavigationMenuLink
      href={link.href}
      closeOnClick
      className='flex-row items-start gap-3'
    >
      <span className='keycap-3d text-muted-foreground flex size-8 shrink-0 items-center justify-center rounded-lg'>
        <link.icon />
      </span>
      <span className='flex flex-col gap-0.5'>
        <span className='text-foreground font-medium'>{link.title}</span>
        <span className='text-muted-foreground text-xs'>
          {link.description}
        </span>
      </span>
    </NavigationMenuLink>
  );
}

function ProductPanel() {
  return (
    <ul className='grid gap-1 sm:w-[34rem] sm:grid-cols-2'>
      {PRODUCT_LINKS.map((link) => (
        <li key={link.title}>
          <IconLink link={link} />
        </li>
      ))}
    </ul>
  );
}

function SolutionsPanel() {
  return (
    <div className='grid gap-4 p-1 sm:w-[24rem] sm:grid-cols-2'>
      {SOLUTION_GROUPS.map((group) => (
        <div key={group.label} className='flex flex-col gap-1'>
          <p className='text-muted-foreground px-2.5 pt-1.5 text-xs font-medium'>
            {group.label}
          </p>
          <ul className='flex flex-col'>
            {group.links.map((link) => (
              <li key={link.title}>
                <NavigationMenuLink
                  href={link.href}
                  className='text-foreground py-2'
                >
                  {link.title}
                </NavigationMenuLink>
              </li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  );
}

function ResourcesPanel() {
  return (
    <div className='grid gap-2 sm:w-[38rem] sm:grid-cols-[minmax(0,1fr)_15rem]'>
      <ul className='flex flex-col gap-1'>
        {RESOURCE_LINKS.map((link) => (
          <li key={link.title}>
            <IconLink link={link} />
          </li>
        ))}
      </ul>
      <NavigationMenuLink
        href={FEATURED_GUIDE.href}
        className='group/guide p-0 transition-[scale] duration-150 ease-(--ease-out-strong) hover:bg-transparent active:scale-[0.97]'
      >
        <span className='bg-foreground/[0.03] group-hover/guide:bg-foreground/[0.05] flex h-full flex-col justify-between gap-6 rounded-lg p-4 transition-colors'>
          <span className='flex flex-col gap-1.5'>
            <span className='text-primary-ink text-xs font-medium'>
              {FEATURED_GUIDE.label}
            </span>
            <span className='text-foreground text-sm font-medium text-balance'>
              {FEATURED_GUIDE.title}
            </span>
            <span className='text-muted-foreground text-xs'>
              {FEATURED_GUIDE.description}
            </span>
          </span>
          <span className='text-primary-ink inline-flex items-center gap-1 text-xs font-medium'>
            Read the guide
            <ArrowRightIcon className='size-3.5' />
          </span>
        </span>
      </NavigationMenuLink>
    </div>
  );
}

export function DesktopNav() {
  return (
    <NavigationMenu className='hidden md:block'>
      <NavigationMenuList>
        <NavigationMenuItem value='product'>
          <NavigationMenuTrigger>Product</NavigationMenuTrigger>
          <NavigationMenuContent>
            <ProductPanel />
          </NavigationMenuContent>
        </NavigationMenuItem>
        <NavigationMenuItem value='solutions'>
          <NavigationMenuTrigger>Solutions</NavigationMenuTrigger>
          <NavigationMenuContent>
            <SolutionsPanel />
          </NavigationMenuContent>
        </NavigationMenuItem>
        <NavigationMenuItem value='resources'>
          <NavigationMenuTrigger>Resources</NavigationMenuTrigger>
          <NavigationMenuContent>
            <ResourcesPanel />
          </NavigationMenuContent>
        </NavigationMenuItem>
        <NavigationMenuItem>
          <NavigationMenuLink
            href='#'
            className={cn(navigationMenuTriggerStyle, 'flex-row py-0')}
          >
            Pricing
          </NavigationMenuLink>
        </NavigationMenuItem>
      </NavigationMenuList>
    </NavigationMenu>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';

import { MenuIcon, XIcon } from '@/registry/ndeko/lib/icons';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/registry/ndeko/ui/accordion';
import { Button } from '@/registry/ndeko/ui/button';
import {
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/registry/ndeko/ui/collapsible';

import {
  type MenuLink,
  PRODUCT_LINKS,
  RESOURCE_LINKS,
  SOLUTION_GROUPS,
} from './data';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const ICON_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW =
  'flex h-10 items-center gap-3 rounded-md px-2 text-sm text-foreground outline-none transition-colors hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25';

function iconVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ICON_VARIANTS;
}

function toggleGlyphOf(isOpen: boolean) {
  if (isOpen) {
    return { key: 'close', icon: <XIcon /> };
  }
  return { key: 'open', icon: <MenuIcon /> };
}

function toggleLabelOf(isOpen: boolean) {
  if (isOpen) {
    return 'Close menu';
  }
  return 'Open menu';
}

export function MobileMenuTrigger({ isOpen }: { isOpen: boolean }) {
  const shouldReduceMotion = useReducedMotion();
  const iconVariants = iconVariantsOf(shouldReduceMotion);
  const glyph = toggleGlyphOf(isOpen);

  return (
    <CollapsibleTrigger
      render={
        <Button
          variant='ghost'
          size='icon'
          className='md:hidden'
          aria-label={toggleLabelOf(isOpen)}
        />
      }
    >
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={glyph.key}
          className='flex'
          variants={iconVariants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {glyph.icon}
        </motion.span>
      </AnimatePresence>
    </CollapsibleTrigger>
  );
}

type NavigateHandler = (event: React.MouseEvent<HTMLAnchorElement>) => void;

type MobileLinksProps = {
  links: MenuLink[];
  onNavigate: NavigateHandler;
};

function MobileIconLinks({ links, onNavigate }: MobileLinksProps) {
  return (
    <ul className='flex flex-col'>
      {links.map((link) => (
        <li key={link.title}>
          <a href={link.href} className={ROW} onClick={onNavigate}>
            <span className='keycap-3d text-muted-foreground flex size-7 shrink-0 items-center justify-center rounded-lg'>
              <link.icon className='size-3.5' />
            </span>
            {link.title}
          </a>
        </li>
      ))}
    </ul>
  );
}

export function MobileMenuPanel({
  onNavigate,
}: {
  onNavigate: NavigateHandler;
}) {
  return (
    <CollapsibleContent className='md:hidden'>
      <nav aria-label='Main' className='flex flex-col gap-4 pt-2 pb-5'>
        <Accordion defaultValue={['product']}>
          <AccordionItem value='product' className='border-b-0'>
            <AccordionTrigger className='px-2 text-sm'>
              Product
            </AccordionTrigger>
            <AccordionContent>
              <MobileIconLinks links={PRODUCT_LINKS} onNavigate={onNavigate} />
            </AccordionContent>
          </AccordionItem>
          <AccordionItem value='solutions' className='border-b-0'>
            <AccordionTrigger className='px-2 text-sm'>
              Solutions
            </AccordionTrigger>
            <AccordionContent className='flex flex-col gap-3'>
              {SOLUTION_GROUPS.map((group) => (
                <div key={group.label} className='flex flex-col gap-0.5'>
                  <p className='text-muted-foreground px-2 py-1 text-xs font-medium'>
                    {group.label}
                  </p>
                  <ul className='flex flex-col'>
                    {group.links.map((link) => (
                      <li key={link.title}>
                        <a
                          href={link.href}
                          className={ROW}
                          onClick={onNavigate}
                        >
                          {link.title}
                        </a>
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </AccordionContent>
          </AccordionItem>
          <AccordionItem value='resources' className='border-b-0'>
            <AccordionTrigger className='px-2 text-sm'>
              Resources
            </AccordionTrigger>
            <AccordionContent>
              <MobileIconLinks links={RESOURCE_LINKS} onNavigate={onNavigate} />
            </AccordionContent>
          </AccordionItem>
        </Accordion>
        <a href='#' className={ROW} onClick={onNavigate}>
          Pricing
        </a>
        <div className='flex flex-col gap-2 px-2'>
          <Button
            variant='outline'
            size='lg'
            nativeButton={false}
            render={<a href='#' />}
          >
            Sign in
          </Button>
          <Button size='lg' nativeButton={false} render={<a href='#' />}>
            Start free
          </Button>
        </div>
      </nav>
    </CollapsibleContent>
  );
}

const SECTION_HASH_PATTERN = /^#.+/;

export function sectionHashOf(href: string | null) {
  if (href === null) {
    return null;
  }
  const isSectionHash = SECTION_HASH_PATTERN.test(href);
  if (!isSectionHash) {
    return null;
  }
  return href;
}

export function scrollToSection(hash: string) {
  const id = hash.slice(1);
  const target = document.getElementById(id);
  target?.scrollIntoView();
}

import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { BoardStage } from './board-stage';
import { HERO } from './data';

export function Hero() {
  return (
    <section className='px-4 pt-16 pb-12 sm:px-6 sm:pt-24 sm:pb-16 lg:px-8'>
      <div className='mx-auto flex max-w-3xl flex-col items-center gap-5 text-center'>
        <p className='text-primary-ink text-xs font-medium'>{HERO.eyebrow}</p>
        <h1 className='text-4xl font-semibold text-balance sm:text-5xl'>
          {HERO.title}
        </h1>
        <p className='text-muted-foreground max-w-xl text-base text-pretty'>
          {HERO.description}
        </p>
        <div className='flex flex-wrap justify-center gap-2 pt-1'>
          <Button size='lg' nativeButton={false} render={<a href='#' />}>
            {HERO.primaryAction}
            <ArrowRightIcon />
          </Button>
          <Button
            size='lg'
            variant='outline'
            nativeButton={false}
            render={<a href='#' />}
          >
            {HERO.secondaryAction}
          </Button>
        </div>
      </div>
      <div className='mx-auto mt-12 max-w-5xl sm:mt-16'>
        <BoardStage />
      </div>
    </section>
  );
}

'use client';

import {
  AnimatePresence,
  LayoutGroup,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useState } from 'react';

import { LayoutGridIcon, ZapIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Kbd } from '@/registry/ndeko/ui/kbd';
import { Switch } from '@/registry/ndeko/ui/switch';

import {
  BOARD,
  BOARD_RULE,
  type BoardCard,
  LANES,
  MOVING_CARD,
  PEOPLE,
  type Person,
} from './data';

const MOVE_INTERVAL_MS = 2800;

const DONE_LANE_INDEX = LANES.length - 1;

const CARD_SPRING: Transition = { type: 'spring', bounce: 0.12, duration: 0.7 };

const INSTANT: Transition = { duration: 0 };

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function nextLaneIndexOf(index: number) {
  const next = index + 1;
  return next % LANES.length;
}

function cardTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return CARD_SPRING;
}

function initialsOf(name: string) {
  const words = name.split(' ');
  const letters = words.map((word) => word.charAt(0));
  return letters.join('');
}

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function laneCountOf(cardCount: number, holdsMovingCard: boolean) {
  if (holdsMovingCard) {
    return cardCount + 1;
  }
  return cardCount;
}

function ruleStatusOf(hasRuleRun: boolean) {
  if (hasRuleRun) {
    return BOARD_RULE.done;
  }
  return BOARD_RULE.waiting;
}

function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={className}>
      <AvatarImage src={person.image} alt={person.name} />
      <AvatarFallback className='text-[10px]'>
        {initialsOf(person.name)}
      </AvatarFallback>
    </Avatar>
  );
}

function BoardCardView({
  card,
  isMoving = false,
}: {
  card: BoardCard;
  isMoving?: boolean;
}) {
  return (
    <div
      className={cn(
        'bg-card hairline-ring ring-border dark:bg-foreground/[0.05] flex flex-col gap-2 rounded-lg p-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)] sm:p-2.5',
        isMoving && 'ring-primary/45 shadow-[0_10px_24px_-10px_rgb(0_0_0/0.22)]'
      )}
    >
      <p className='line-clamp-2 text-xs leading-snug font-medium sm:text-[13px]'>
        {card.title}
      </p>
      <div className='flex items-center justify-between gap-1'>
        <Chip color='var(--muted-foreground)'>{card.label}</Chip>
        <PersonAvatar
          person={card.owner}
          className='hidden size-5 sm:inline-flex'
        />
      </div>
    </div>
  );
}

function BoardHeader() {
  return (
    <div className='flex items-center gap-2.5 px-3 pt-3 sm:px-4 sm:pt-4'>
      <span className='gem-plate flex size-6 items-center justify-center rounded-md [--gem:var(--primary)]'>
        <LayoutGridIcon className='size-3.5' />
      </span>
      <p className='text-sm font-medium'>{BOARD.title}</p>
      <Chip color='var(--muted-foreground)' className='hidden sm:inline-flex'>
        {BOARD.week}
      </Chip>
      <div className='ms-auto flex -space-x-1.5'>
        {PEOPLE.map((person) => (
          <PersonAvatar
            key={person.name}
            person={person}
            className='ring-card size-6 ring-2'
          />
        ))}
      </div>
    </div>
  );
}

function RuleCard({ hasRuleRun }: { hasRuleRun: boolean }) {
  const shouldReduceMotion = useReducedMotion();
  const status = ruleStatusOf(hasRuleRun);
  const swapVariants = swapVariantsOf(shouldReduceMotion);

  return (
    <div className='surface-raised motion-safe:animate-float absolute right-4 -bottom-6 hidden w-64 items-center gap-3 rounded-xl p-3 sm:flex lg:right-8'>
      <span className='keycap-3d text-muted-foreground flex size-8 shrink-0 items-center justify-center rounded-lg'>
        <ZapIcon />
      </span>
      <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
        <p className='truncate text-[13px] font-medium'>{BOARD_RULE.trigger}</p>
        <AnimatePresence mode='popLayout' initial={false}>
          <motion.p
            key={status}
            className='text-muted-foreground truncate text-xs'
            variants={swapVariants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={SWAP_TRANSITION}
          >
            {status}
          </motion.p>
        </AnimatePresence>
      </div>
      <Switch defaultChecked aria-label='Rule is on' />
    </div>
  );
}

export function BoardStage() {
  const [movingLaneIndex, setMovingLaneIndex] = useState(0);
  const shouldReduceMotion = useReducedMotion();
  const cardTransition = cardTransitionOf(shouldReduceMotion);
  const hasRuleRun = movingLaneIndex === DONE_LANE_INDEX;

  useEffect(() => {
    if (shouldReduceMotion) {
      return;
    }
    const interval = window.setInterval(() => {
      setMovingLaneIndex(nextLaneIndexOf);
    }, MOVE_INTERVAL_MS);
    return () => window.clearInterval(interval);
  }, [shouldReduceMotion]);

  return (
    <div
      inert
      aria-hidden='true'
      className='bg-foreground/[0.025] relative rounded-2xl p-3 pb-10 sm:p-6 sm:pb-12'
    >
      <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col gap-3 rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.12)] sm:gap-4'>
        <BoardHeader />
        <LayoutGroup id='marketing-01-board'>
          <div className='grid grid-cols-3 gap-2 px-2 pb-2 sm:gap-3 sm:px-4 sm:pb-4'>
            {LANES.map((lane, index) => {
              const holdsMovingCard = index === movingLaneIndex;
              const count = laneCountOf(lane.cards.length, holdsMovingCard);

              return (
                <div
                  key={lane.id}
                  className='bg-foreground/[0.03] flex min-w-0 flex-col gap-2 rounded-lg p-1.5 sm:p-2'
                >
                  <div className='flex items-center justify-between gap-1 px-1 pt-0.5'>
                    <span className='truncate text-xs font-medium'>
                      {lane.title}
                    </span>
                    <Kbd>{count}</Kbd>
                  </div>
                  {holdsMovingCard && (
                    <motion.div
                      layoutId='marketing-01-moving-card'
                      transition={cardTransition}
                      className='relative z-10'
                    >
                      <BoardCardView card={MOVING_CARD} isMoving />
                    </motion.div>
                  )}
                  {lane.cards.map((card) => (
                    <motion.div
                      key={card.id}
                      layout='position'
                      transition={cardTransition}
                    >
                      <BoardCardView card={card} />
                    </motion.div>
                  ))}
                </div>
              );
            })}
          </div>
        </LayoutGroup>
      </div>
      <RuleCard hasRuleRun={hasRuleRun} />
    </div>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

import { LOGO_CLOUD, MARKS } from './data';
import { MarkShape } from './mark-shape';

const MARQUEE_LOOP = [...MARKS, ...MARKS];

function isRepeatedMark(index: number) {
  return index >= MARKS.length;
}

function hiddenFromReadersOf(isRepeated: boolean) {
  if (isRepeated) {
    return true;
  }
  return undefined;
}

export function LogoCloud() {
  return (
    <section className='px-4 py-12 sm:px-6 sm:py-16 lg:px-8'>
      <div className='mx-auto flex max-w-6xl flex-col gap-8'>
        <h2 className='text-muted-foreground text-center text-sm font-medium text-balance'>
          {LOGO_CLOUD.title}
        </h2>
        <div className='group relative overflow-hidden mask-x-from-85% motion-reduce:mask-none'>
          <ul className='motion-safe:animate-marquee flex w-max [--marquee-duration:44s] group-hover:[animation-play-state:paused] motion-reduce:w-full motion-reduce:flex-wrap motion-reduce:justify-center motion-reduce:gap-y-6'>
            {MARQUEE_LOOP.map((mark, index) => {
              const isRepeated = isRepeatedMark(index);

              return (
                <li
                  key={`${mark.name}-${index}`}
                  aria-hidden={hiddenFromReadersOf(isRepeated)}
                  className={cn(
                    'text-foreground/55 flex shrink-0 items-center gap-2.5 px-6 sm:px-9',
                    isRepeated && 'motion-reduce:hidden'
                  )}
                >
                  <MarkShape shape={mark.shape} />
                  <span className='text-base font-semibold whitespace-nowrap'>
